mapper.update:
UPDATE  EMAIL_VERIFICATION
SET     USED_AT = #{now},
        UPDATED_AT = #{now}
WHERE   EMAIL_HASH = #{emailHash}
  AND   VERIFY_TYPE = #{type}
  AND   USED_AT IS NULL
  AND   EXPIRES_AT > #{now}
  AND   (LOCKED_UNTIL IS NULL OR LOCKED_UNTIL <= #{now})
  AND   CODE_HASH = #{codeHash}

UPDATE  EMAIL_VERIFICATION
SET     ATTEMPTS = ATTEMPTS + 1,
        LOCKED_UNTIL = CASE
            WHEN ATTEMPTS + 1 >= #{maxAttempts} THEN #{lockedUntil}
            ELSE LOCKED_UNTIL
        END,
        UPDATED_AT = #{now}
WHERE   EMAIL_HASH = #{emailHash}
  AND   VERIFY_TYPE = #{type}
  AND   USED_AT IS NULL
  AND   EXPIRES_AT > #{now}
